const labels: Record<string, string> = { needs_review: 'Needs Review', changes_requested: 'Changes Requested', changes_planned: 'Changes Planned', abandoned: 'Abandoned', in_progress: 'In Progress', accepted: 'Accepted', draft: 'Draft', closed: 'Closed', open: 'Open', resolved: 'Resolved', duplicate: 'Duplicate' };
function human(value: string): string { return isRevisionStatus(value) ? revisionStatusLabel(value) : labels[value] || value; }
function time(value: string): string { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }); }
function relative(value: string): string { const mins = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 60000)); return mins < 1 ? 'just now' : mins < 60 ? `${mins}m ago` : mins < 1440 ? `${Math.floor(mins / 60)}h ago` : time(value); }
function Badge({ value }: { value: string }) { return <span className={`badge badge-${value}`}>{human(value)}</span>; }
function Empty({ icon: Icon = Inbox, children }: { icon?: Icon; children: ReactNode }) { return <div className="empty"><Icon size={30} strokeWidth={1.4} /><div>{children}</div></div>; }
function Panel({ title, icon: Icon, extra, children, className = '' }: { title: string; icon?: Icon; extra?: ReactNode; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-heading"><h2>{Icon && <Icon size={17} />}{title}</h2>{extra}</div>{children}</section>; }
