  const [draft, setDraft, draftPersisted] = useDraft<Record<string, string>>(draftKey, { title: document?.title || taskTitle, name: '', description: '', summary: '', testPlan: '', priority: 'normal', ownerId: '', projectIds: '[]', projectId: '', repositoryId: '', content: document?.content || (paper ? '\\documentclass{article}\n\\title{Untitled paper}\n\\author{}\n\\begin{document}\n\\maketitle\n\\section{Introduction}\n\n\\end{document}\n' : ''), slug: document?.slug || '', path: paper ? 'main.tex' : isDraft ? 'motion.md' : 'src/main.ts', remoteUrl: '', defaultBranch: 'main', color: '#2980b9', colorKey: 'blue', icon: 'project', aliases: '', memberIds: '[]', message: '', spaceId: state.spaces.find(space => space.isDefault && !space.archived)?.id || '' });
