  const revisionMetadataError = kind === 'revision' ? creationMetadataError({ title: draft.title || '', summary: draft.summary, testPlan: draft.testPlan || '' }, state) : null;
  const held = kind === 'revision' && draftIsHeld(draftKey);
  const canSave = !held && (document ? Boolean(state.access[document.id]?.capabilities.edit && !oldWikiRename) : state.canCreate && state.spaces.some(space => space.id === draft.spaceId && !space.archived));
