  const initialMembers: string[] = useMemo(() => { try { const value: unknown = JSON.parse(draft.memberIds || '[]'); return Array.isArray(value) ? value.filter((id): id is string => typeof id === 'string') : []; } catch { return []; } }, [draft.memberIds]);
