    if (kind === 'project') await mutate('/api/projects', 'POST', { ...placement, name: draft.name, description: draft.description, ...(draft.colorKey && draft.colorKey !== 'custom' ? { colorKey: draft.colorKey } : { color: draft.color }), icon: draft.icon || 'project', aliases: (draft.aliases || '').split('\n').map(value => value.trim()).filter(Boolean), memberIds: initialMembers }, 'Project created', initialMembers.length === 0);
