function canRenderReviewSource(content: string): boolean {
  if (content.length > COMPARISON_LIMITS.maxRenderedCodeUnits) return false;
  let lines = 1; for (let index = 0; index < content.length; index++) if (content[index] === '\n' && ++lines > COMPARISON_LIMITS.maxSourceLines) return false;
  return true;
}

